// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.componentsimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.borderimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.CircleShapeimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.alphaimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport com.roshan.persona.ui.theme.personaColor/** * Persona avatar — circular with persona-specific accent color and initial letter. * * No images — uses the persona's name initial as the glyph, on a colored circle. * This is real (no fake avatar URLs, no asset dependencies). * * @param personaId e.g. "atlas", "nova" — drives the accent color * @param displayName used to extract the initial letter * @param size dp size of the avatar (default 48) * @param enabled when false, dims the avatar (used for inactive personas) */@Composablefun PersonaAvatar(    personaId: String?,    displayName: String,    modifier: Modifier = Modifier,    size: androidx.compose.ui.unit.Dp = 48.dp,    enabled: Boolean = true,) {    val color = personaColor(personaId)    val initial = displayName.firstOrNull()?.uppercase() ?: "?"    Box(        modifier = modifier            .size(size)            .alpha(if (enabled) 1f else 0.4f)            .background(                color = color.copy(alpha = 0.2f),                shape = CircleShape,            )            .border(                width = 2.dp,                color = color,                shape = CircleShape,            ),        contentAlignment = Alignment.Center,    ) {        Text(            text = initial,            color = color,            fontWeight = FontWeight.Bold,            fontSize = (size.value * 0.45f).sp,        )    }}/** * Layer badge — small pill showing "L4" with the layer's color. */@Composablefun LayerBadge(    layerName: String,    modifier: Modifier = Modifier,) {    val color = com.roshan.persona.ui.theme.brainLayerColor(layerName)    Box(        modifier = modifier            .background(                color = color.copy(alpha = 0.25f),                shape = androidx.compose.foundation.shape.RoundedCornerShape(8.dp),            )            .border(                width = 1.dp,                color = color,                shape = androidx.compose.foundation.shape.RoundedCornerShape(8.dp),            ),    ) {        Text(            text = layerName,            style = MaterialTheme.typography.labelSmall,            color = color,            modifier = Modifier                .align(Alignment.Center)                .padding(horizontal = 6.dp, vertical = 2.dp),        )    }}/** * Confidence bar — horizontal bar showing 0-100% with color tier. * * @param value 0f..1f * @param width bar width */@Composablefun ConfidenceBar(    value: Float,    modifier: Modifier = Modifier,    width: androidx.compose.ui.unit.Dp = 120.dp,) {    val clamped = value.coerceIn(0f, 1f)    val color = when {        clamped >= 0.7f -> com.roshan.persona.ui.theme.AccentSuccess        clamped >= 0.5f -> com.roshan.persona.ui.theme.AccentWarn        else -> com.roshan.persona.ui.theme.AccentDanger    }    Box(        modifier = modifier            .size(width = width, height = 6.dp)            .background(                color = MaterialTheme.colorScheme.surfaceVariant,                shape = androidx.compose.foundation.shape.RoundedCornerShape(3.dp),            ),    ) {        Box(            modifier = Modifier                .size(width = width * clamped, height = 6.dp)                .background(                    color = color,                    shape = androidx.compose.foundation.shape.RoundedCornerShape(3.dp),                ),        )    }}